_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago", "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh", "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo", "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
# locale -> (decimal, group, code_before)
_LOCALES = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True), "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if int(m.group(3) or 0):
            raise ValueError(f"unsupported fixed offset {tz}")
        if hours == 0:
            return "Etc/UTC"
        sign = "-" if m.group(1) == "+" else "+"
        return f"Etc/GMT{sign}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if tz.upper() in ("UTC", "GMT", "Z", "ETC/UTC"):
        return "Etc/UTC"
    return _link_target(tz) or tz


def _link_target(name: str) -> str | None:
    import glob
    import os
    paths = glob.glob("/usr/share/zoneinfo/tzdata.zi") + glob.glob("/usr/share/zoneinfo/*/tzdata.zi")
    try:
        import tzdata  # type: ignore
        paths.append(os.path.join(os.path.dirname(tzdata.__file__), "zoneinfo", "tzdata.zi"))
    except ImportError:
        pass
    for path in paths:
        try:
            with open(path) as f:
                for line in f:
                    parts = line.split()
                    if len(parts) == 3 and parts[0] == "L" and parts[2] == name:
                        return parts[1]
        except OSError:
            continue
    return None


def _locale(raw: str) -> str:
    base = re.split(r"[.@]", raw.strip())[0].replace("_", "-")
    parts = base.split("-")
    lang = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and parts[1] else ""
    tag = f"{lang}-{region}" if region else lang
    if tag in _LOCALES:
        return tag
    if lang in _LOCALES:
        return lang
    return "en-US"


def _group(intpart: str, loc: str, sep: str) -> str:
    if loc == "es" and len(intpart) == 4:
        return intpart
    if loc == "en-IN" and len(intpart) > 3:
        head, tail = intpart[:-3], intpart[-3:]
        chunks = []
        while len(head) > 2:
            chunks.insert(0, head[-2:])
            head = head[:-2]
        if head:
            chunks.insert(0, head)
        return sep.join(chunks + [tail])
    chunks = []
    while len(intpart) > 3:
        chunks.insert(0, intpart[-3:])
        intpart = intpart[:-3]
    return sep.join([intpart] + chunks)


def _format(value: Decimal, currency: str, loc: str) -> str:
    dec, grp, before = _LOCALES[loc]
    n = _digits(currency)
    value = value.quantize(Decimal(1).scaleb(-n))
    neg = value < 0
    text = f"{abs(value):.{n}f}"
    intpart, _, frac = text.partition(".")
    num = _group(intpart, loc, grp) + (dec + frac if n else "")
    if neg:
        num = "-" + num
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    loc = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": loc,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    n = _digits(cur)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = _amount(d["gross"], n), _amount(d["fees"], n), _amount(d["refunds"], n)
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _format(net, cur, loc)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-n))
    return Statement(merchant.id, cur, tuple(lines), total, _format(total, cur, loc))
'''
